Cypher query: MATCH (a:Article)-[r:PUBLISHED_BY]->(p:Publisher)
WHERE (toLower(p.name) CONTAINS 'the sydney morning herald' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the sydney morning herald'))
OPTIONAL MATCH (a)-[:MENTIONS]->(e)
WITH a, p, r, collect(DISTINCT e.name) AS mentions
