Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p)
MATCH (a)-[r]-(e:__Entity__)
WITH a, p, r, e,
     toLower(a.name) + ' ' + reduce(s = '', alias IN coalesce(a.aliases, []) | s + ' ' + toLower(alias)) AS articleText
WHERE (toLower(p.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
  AND articleText CONTAINS 'google'
  AND (
    articleText CONTAINS 'anticompetitive'
    OR (articleText CONTAINS 'app' AND articleText CONTAINS 'distribution')
    OR (articleText CONTAINS 'payment' AND articleText CONTAINS 'processing')
    OR (articleText CONTAINS 'news' AND (articleText CONTAINS 'publisher' OR articleText CONTAINS 'media'))
  )
  OR (
    (toLower(p.name) CONTAINS 'the age' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the age'))
    AND articleText CONTAINS 'google'
    AND articleText CONTAINS 'search'
    AND (articleText CONTAINS 'fair' OR articleText CONTAINS 'fairness')
  )
RETURN DISTINCT a.name AS article, p.name AS publisher, a.published_on AS published_on, type(r) AS relationship, e.name AS connected_entity
LIMIT 10
